class Buffer:
    def __init__(self):
        self.items = []
    def append(self, value):
        self.items.append(value)

def store(value):
    registry = {'archive': Buffer()}
    return registry['archive'].append(value)

class Writer:
    def append(self, value):
        with open('events.txt', 'a', encoding='utf-8') as stream:
            stream.write(value)

def store(value):
    registry = {'archive': Writer()}
    return registry['archive'].append(value)

def store(value, lookup):
    backend = lookup('archive')
    return backend.append(value)

class Disk:
    def write(self, value):
        with open('events.txt', 'a') as stream:
            stream.write(value)

class Memory:
    def write(self, value):
        return [value]

def store(value, persistent=False):
    registry = {'active': Disk() if persistent else Memory()}
    return registry['active'].write(value)
